def doctorStrange(N, M, graph):
    def dfs(node, visited):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited)

    def count_components():
        visited = [False] * (N + 1)
        components = 0
        for i in range(1, N + 1):
            if not visited[i]:
                dfs(i, visited)
                components += 1
        return components

    original_components = count_components()
    result = 0

    for i in range(1, N + 1):
        temp_graph = [[] for _ in range(N + 1)]
        for j in range(1, N + 1):
            if j != i:
                temp_graph[j] = graph[j][:]
        if count_components() > original_components:
            result += 1

    return result
